using ClosedXML.Excel;using WhatsBiz.Application.Common.Interfaces;using WhatsBiz.Domain.Inventory;
namespace WhatsBiz.Infrastructure.Inventory;
public sealed class InventorySpreadsheetService:IInventorySpreadsheetService{public byte[] ExportBalances(IReadOnlyCollection<InventoryBalance> balances){using var book=new XLWorkbook();var sheet=book.AddWorksheet("Stock Balance");string[] headers=["Product Code","Product Name","Warehouse","Zone","Bin","Batch","Serial","On Hand","Reserved","Available","Average Cost","Stock Value","Last Updated"];for(var i=0;i<headers.Length;i++)sheet.Cell(1,i+1).Value=headers[i];sheet.Row(1).Style.Font.Bold=true;var row=2;foreach(var x in balances){sheet.Cell(row,1).Value=x.Product.ProductCode;sheet.Cell(row,2).Value=x.Product.ProductName;sheet.Cell(row,3).Value=x.Warehouse.WarehouseName;sheet.Cell(row,4).Value=x.Zone?.ZoneCode;sheet.Cell(row,5).Value=x.Bin?.BinCode;sheet.Cell(row,6).Value=x.BatchNo;sheet.Cell(row,7).Value=x.SerialNo;sheet.Cell(row,8).Value=x.QuantityOnHand;sheet.Cell(row,9).Value=x.QuantityReserved;sheet.Cell(row,10).Value=x.QuantityAvailable;sheet.Cell(row,11).Value=x.AverageCost;sheet.Cell(row,12).Value=x.QuantityOnHand*x.AverageCost;sheet.Cell(row,13).Value=x.LastUpdated.DateTime;row++;}sheet.Columns().AdjustToContents();using var stream=new MemoryStream();book.SaveAs(stream);return stream.ToArray();}}
